>@php($variants=old('variants',$product->variants->toArray() ?: [['sku'=>'','color'=>'Trắng','size'=>'40','price'=>'','stock'=>'0']]))@foreach($variants as $i=>$variant)<div class="variant-row"><input name="variants[{{ $i }}][sku]" placeholder="SKU" value="{{ $variant['sku'] }}" required><input name="variants[{{ $i }}][color]" placeholder="Màu" value="{{ $variant['color'] }}" required><input name="variants[{{ $i }}][size]" placeholder="Size" value="{{ $variant['size'] }}" required><input name="variants[{{ $i }}][price]" type="number" placeholder="Giá" value="{{ $variant['price'] }}" required><input name="variants[{{ $i }}][stock]" type="number" placeholder="Tồn" value="{{ $variant['stock'] }}" required></div>@endforeach</div><button class="btn small" type="button" id="addVariant" style="margin-top:10px">+ THÊM BIẾN THỂ</button></div>@if($product->images->count())<div class="variants"><b>ẢNH ĐANG CÓ</b><div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">@foreach($product->images as $image)<img class="thumb" src="{{ str_starts_with($image->path,'http')?$image->path:asset('storage/'.$image->path) }}" alt="">@endforeach</div></div>@endif<div style="margin-top:25px"><button class="btn lime">{{ $product->exists?'LƯU THAY ĐỔI':'TẠO SẢN PHẨM' }} →</button></div></form><script>let n={{ count($variants) }};document.getElementById('addVariant').onclick=()=>{document.getElementById('variantRows').insertAdjacentHTML('beforeend',`<div class="variant-row"><input name="variants[${n}][sku]" placeholder="SKU" required><input name="variants[${n}][color]" placeholder="Màu" value="Trắng" required><input name="variants[${n}][size]" placeholder="Size" value="40" required><input name="variants[${n}][price]" type="number" placeholder="Giá" required><input name="variants[${n}][stock]" type="number" placeholder="Tồn" value="0" required></div>`);n++}</script>@endsection
